+package r.base.random;
+
+import r.base.Distributions;
+
+public class Binom {
+
+  public static double rbinom(double nin, double pp) {
+
+    /* static */
+    double c = 0, fm = 0, npq = 0, p1 = 0, p2 = 0, p3 = 0, p4 = 0, qn = 0;
+    double xl = 0, xll = 0, xlr = 0, xm = 0, xr = 0;
+    double psave = -1.0;
+    int nsave = -1;
+    int m = 0;
+    /* end of static */
+
+    double f, f1, f2, u, v, w, w2, x, x1, x2, z, z2;
+    double p, q, np, g, r, al, alv, amaxp, ffm, ynorm;
+    int i, ix, k, n;
+
+    if (Double.isInfinite(nin)) {
+      return Double.NaN;
+    }
+    r = Math.floor(nin + 0.5);
+    if (r != nin) {
+      return Double.NaN;
+    }
+    if (Double.isInfinite(pp) || r < 0 || pp < 0. || pp > 1.) {
+      return Double.NaN;
+    }
+
+    if (r == 0 || pp == 0.) {
+      return 0;
+    }
+    if (pp == 1.) {
+      return r;
+    }
+
+    if (r >= Integer.MAX_VALUE) {
+      return Distributions.qbinom(RNG.unif_rand(), (int) r, pp, false,
false);
+    }
+    /* else */
+    n = (int) r;
+
+    p = Math.min(pp, 1. - pp);
+    q = 1. - p;
+    np = n * p;
+    r = p / q;
+    g = r * (n + 1);
+
+    /* Setup, perform only when parameters change [using static (globals):
*/
+
+    /* FIXING: Want this thread safe
+    -- use as little (thread globals) as possible
+     */
+    if (pp != psave || n != nsave) {
+      psave = pp;
+      nsave = n;
+      if (np < 30.0) {
+        /* inverse cdf logic for mean less than 30 */
+        qn = Math.pow(q, (double) n);
+
+
+
+
+        /*---------------------- np = n*p < 30 : -------------------------
*/
+        while (true) {
+          ix = 0;
+          f = qn;
+          u = RNG.unif_rand();
+          while (true) {
+            if (u < f) {
+              if (psave > 0.5) {
+                ix = n - ix;
+              }
+              return (double) ix;
+            }
+            if (ix > 110) {
+              break;
+            }
+            u -= f;
+            ix++;
+            f *= (g / ix - r);
+          }
+        }
+
+
+
+      } else {
+        ffm = np + p;
+        m = (int) ffm;
+        fm = m;
+        npq = np * q;
+        p1 = (int) (2.195 * Math.sqrt(npq) - 4.6 * q) + 0.5;
+        xm = fm + 0.5;
+        xl = xm - p1;
+        xr = xm + p1;
+        c = 0.134 + 20.5 / (15.3 + fm);
+        al = (ffm - xl) / (ffm - xl * p);
+        xll = al * (1.0 + 0.5 * al);
+        al = (xr - ffm) / (xr * q);
+        xlr = al * (1.0 + 0.5 * al);
+        p2 = p1 * (1.0 + c + c);
+        p3 = p2 + c / xll;
+        p4 = p3 + c / xlr;
+      }
+    } else if (n == nsave) {
+      if (np < 30.0) {
+      }
+
+
+
+      /*---------------------- np = n*p < 30 : ------------------------- */
+      while (true) {
+        ix = 0;
+        f = qn;
+        u = RNG.unif_rand();
+        while (true) {
+          if (u < f) {
+            if (psave > 0.5) {
+              ix = n - ix;
+            }
+            return (double) ix;
+          }
+          if (ix > 110) {
+            break;
+          }
+          u -= f;
+          ix++;
+          f *= (g / ix - r);
+        }
+      }
+
+    }
+
+    /*-------------------------- np = n*p >= 30 : ------------------- */
+    while (true) {
+      u = RNG.unif_rand() * p4;
+      v = RNG.unif_rand();
+      /* triangular region */
+      if (u <= p1) {
+        ix = (int) (xm - p1 * v + u);
+
+        if (psave > 0.5) {
+          ix = n - ix;
+        }
+        return (double) ix;
+      }
+      /* parallelogram region */
+      if (u <= p2) {
+        x = xl + (u - p1) / c;
+        v = v * c + 1.0 - Math.abs(xm - x) / p1;
+        if (v > 1.0 || v <= 0.) {
+          continue;
+        }
+        ix = (int) x;
+      } else {
+        if (u > p3) {	/* right tail */
+          ix = (int) (xr - Math.log(v) / xlr);
+          if (ix > n) {
+            continue;
+          }
+          v = v * (u - p3) * xlr;
+        } else {/* left tail */
+          ix = (int) (xl + Math.log(v) / xll);
+          if (ix < 0) {
+            continue;
+          }
+          v = v * (u - p2) * xll;
+        }
+      }
+      /* determine appropriate way to perform accept/reject test */
+      k = Math.abs(ix - m);
+      if (k <= 20 || k >= npq / 2 - 1) {
+        /* explicit evaluation */
+        f = 1.0;
+        if (m < ix) {
+          for (i = m + 1; i <= ix; i++) {
+            f *= (g / i - r);
+          }
+        } else if (m != ix) {
+          for (i = ix + 1; i <= m; i++) {
+            f /= (g / i - r);
+          }
+        }
+        if (v <= f) {
+          if (psave > 0.5) {
+            ix = n - ix;
+          }
+          return (double) ix;
+        }
+
+
+      } else {
+        /* squeezing using upper and lower bounds on log(f(x)) */
+        amaxp = (k / npq) * ((k * (k / 3. + 0.625) + 0.1666666666666) /
npq + 0.5);
+        ynorm = -k * k / (2.0 * npq);
+        alv = Math.log(v);
+        if (alv < ynorm - amaxp) {
+          if (psave > 0.5) {
+            ix = n - ix;
+          }
+          return (double) ix;
+        }
+
+
+
+        if (alv <= ynorm + amaxp) {
+          /* stirling's formula to machine accuracy */
+          /* for the final acceptance/rejection test */
+          x1 = ix + 1;
+          f1 = fm + 1.0;
+          z = n + 1 - fm;
+          w = n - ix + 1.0;
+          z2 = z * z;
+          x2 = x1 * x1;
+          f2 = f1 * f1;
+          w2 = w * w;
+          if (alv <= xm * Math.log(f1 / x1) + (n - m + 0.5) * Math.log(z /
w) + (ix - m) * Math.log(w * p / (x1 * q)) + (13860.0 - (462.0 - (132.0 -
(99.0 - 140.0 / f2) / f2) / f2) / f2) / f1 / 166320.0 + (13860.0 - (462.0 -
(132.0 - (99.0 - 140.0 / z2) / z2) / z2) / z2) / z / 166320.0 + (13860.0 -
(462.0 - (132.0 - (99.0 - 140.0 / x2) / x2) / x2) / x2) / x1 / 166320.0 +
(13860.0 - (462.0 - (132.0 - (99.0 - 140.0 / w2) / w2) / w2) / w2) / w /
166320.) {
+          }
+
+          if (psave > 0.5) {
+            ix = n - ix;
+          }
+          return (double) ix;
+        }
+      }
+    }
+
+  }
+}
