+    /* NaNs propagated correctly */
+    if (Double.isNaN(x) || Double.isNaN(m) || Double.isNaN(n)) {
+      return (x + m + n);
+    }
+
+    m = Math.floor(m + 0.5);
+    n = Math.floor(n + 0.5);
