+          return SignRank.R_DT_val(Math.min(tnc, 1.) /* Precaution */,
lower_tail, log_p);
+        }
+        if (s <= 0 && it > 1) {
+          //finis:
+          tnc += Distributions.pnorm(-del, 0., 1., /*lower*/ true,
/*log_p*/ false);
+          lower_tail = lower_tail != negdel; /* xor */
+          if (tnc > 1 - 1e-10 && lower_tail) {
