+        }/*convergence*/
+      }
+      /* non-convergence:*/
+      //ML_ERROR(ME_NOCONV, "pnt");
+    } else { /* x = t = 0 */
+      tnc = 0.;
+    }
+    //finis:
+    tnc += Distributions.pnorm(-del, 0., 1., /*lower*/ true, /*log_p*/
