+    /* R has  M_1_SQRT_2PI , and M_LN_SQRT_2PI = ln(sqrt(2*pi)) =
0.918938.. */
+
+    int i, n;
+    double c, e, h, t, u, v, z, a0, b0, x0, y0, apb, lnx, lny;
+    double lambda;
+
+
+    if (x == 0.0 || y == 0.0) {
+      return SignRank.R_D__0( true, log_p);
+    }
+    a0 = Math.min(a, b);
+    if (a0 >= 8.0) {
+        if (a <= b) {
+	h = a / b;
+	x0 = h / (h + 1.0);
+	y0 = 1.0 / (h + 1.0);
+	lambda = a - (a + b) * x;
+    } else {
+	h = b / a;
+	x0 = 1.0 / (h + 1.0);
+	y0 = h / (h + 1.0);
+	lambda = (a + b) * y - b;
+    }
+
+    e = -lambda / a;
+    if (Math.abs(e) > .6)
+	u = e - Math.log(x / x0);
+    else
+	u = rlog1(e);
+
+    e = lambda / b;
+    if (Math.abs(e) <= .6)
+	v = rlog1(e);
+    else
+	v = e - Math.log(y / y0);
+
+    z = log_p ? -(a * u + b * v) : Math.exp(-(a * u + b * v));
+
+    return(log_p
+	   ? -Math.log(Math.sqrt(2.0* Math.PI)) + .5*Math.log(b * x0) + z -
bcorr(a,b)
+	   : const__ * Math.sqrt(b * x0) * z * Math.exp(-bcorr(a, b)));
+    }
+
+    if (x <= .375) {
+	lnx = Math.log(x);
+	lny = alnrel(-x);
+    }
+    else {
+	if (y > .375) {
+	    lnx = Math.log(x);
+	    lny = Math.log(y);
+	} else {
+	    lnx = alnrel(-y);
+	    lny = Math.log(y);
+	}
