+	} else {
+	    z = gam1(apb) + 1.0;
+	}
+
+	c = (gam1(a) + 1.0) * (gam1(b) + 1.0) / z;
+	/* FIXME? log(a0*c)= log(a0)+ log(c) and that is improvable */
+	return (log_p
+		? e_z + Math.log(a0 * c) - Math.log1p(a0/b0)
