+      mid = Poisson.dpois_raw(imax, ncp2, false) * Distributions.dchisq(x,
dfmid, false);
+    } else /* imax = Inf */ {
+      mid = 0;
+    }
+
+    if (mid == 0) {
+      /* underflow to 0 -- maybe numerically correct; maybe can be more
accurate,
+       * particularly when  give_log = TRUE */
+      /* Use  central-chisq approximation formula when appropriate;
+       * ((FIXME: the optimal cutoff also depends on (x,df);  use always
here? )) */
+      if (give_log || ncp > 1000.) {
+        double nl = df + ncp, ic = nl / (nl + ncp);/* = "1/(1+b)"
Abramowitz & St.*/
+        return Distributions.dchisq(x * ic, nl * ic, give_log);
+      } else {
+        return SignRank.R_D__0(true, give_log);
+      }
+    }
+
+    sum = mid;
+
+    /* errorbound := term * q / (1-q)  now subsumed in while() / if()
below: */
+
+    /* upper tail */
+    term = mid;
+    df = dfmid;
+    i = imax;
+    double x2 = x * ncp2;
+    do {
+      i++;
+      q = x2 / i / df;
+      df += 2;
+      term *= q;
+      sum += term;
+    } while (q >= 1 || term * q > (1 - q) * eps || term > 1e-10 * sum);
+    /* lower tail */
+    term = mid;
+    df = dfmid;
+    i = imax;
+    while (i >= 0) {
+      df -= 2;
+      q = i * df / x2;
+      i--;
+      term *= q;
+      sum += term;
+      if (q < 1 && term * q <= (1 - q) * eps) {
+        break;
+      }
+    }
+    return SignRank.R_D_val(sum, true, give_log);
+  }
+}
