+    public static void L20() {
+      if (u > p) {
+        u -= p;
+        p *= (n1 - ix) * (k - ix);
+        ix++;
+        p = p / ix / (n2 - k + ix);
+        if (ix > maxjx) {
+          L10();
+        }
+        L20();
+      }
+    }
+
+    public static void L30() {
+      u = RNG.unif_rand() * p3;
+      v = RNG.unif_rand();
+      if (u < p1) { /* rectangular region */
+        ix = (int) (xl + u);
+      } else if (u <= p2) { /* left tail */
+        ix = (int) (xl + Math.log(v) / lamdl);
+        if (ix < minjx) {
+          L30();
+        }
+        v = v * (u - p1) * lamdl;
+      } else { /* right tail */
+        ix = (int) (xr - Math.log(v) / lamdr);
+        if (ix > maxjx) {
+          L30();
+        }
+        v = v * (u - p2) * lamdr;
+      }
+
+      /* acceptance/rejection test */
+
+      if (m < 100 || ix <= 50) {
+        /* explicit evaluation */
+        /* The original algorithm (and TOMS 668) have
+        f = f * i * (n2 - k + i) / (n1 - i) / (k - i);
+        in the (m > ix) case, but the definition of the
+        recurrence relation on p134 shows that the +1 is
+        needed. */
+        f = 1.0;
+        if (m < ix) {
+          for (i = m + 1; i <= ix; i++) {
+            f = f * (n1 - i + 1) * (k - i + 1) / (n2 - k + i) / i;
+          }
+        } else if (m > ix) {
+          for (i = ix + 1; i <= m; i++) {
+            f = f * i * (n2 - k + i) / (n1 - i + 1) / (k - i + 1);
+          }
+        }
+        if (v <= f) {
+          reject = false;
+        }
+      } else {
+        /* squeeze using upper and lower bounds */
+        y = ix;
+        y1 = y + 1.0;
+        ym = y - m;
+        yn = n1 - y + 1.0;
+        yk = k - y + 1.0;
+        nk = n2 - k + y1;
+        r = -ym / y1;
+        s = ym / yn;
+        t = ym / yk;
+        e = -ym / nk;
+        g = yn * yk / (y1 * nk) - 1.0;
+        dg = 1.0;
+        if (g < 0.0) {
+          dg = 1.0 + g;
+        }
+        gu = g * (1.0 + g * (-0.5 + g / 3.0));
+        gl = gu - .25 * (g * g * g * g) / dg;
+        xm = m + 0.5;
+        xn = n1 - m + 0.5;
+        xk = k - m + 0.5;
+        nm = n2 - k + xm;
+        ub = y * gu - m * gl + deltau
+                + xm * r * (1. + r * (-0.5 + r / 3.0))
+                + xn * s * (1. + s * (-0.5 + s / 3.0))
+                + xk * t * (1. + t * (-0.5 + t / 3.0))
+                + nm * e * (1. + e * (-0.5 + e / 3.0));
+        /* test against upper bound */
+        alv = Math.log(v);
+        if (alv > ub) {
+          reject = true;
+        } else {
+          /* test against lower bound */
+          dr = xm * (r * r * r * r);
+          if (r < 0.0) {
+            dr /= (1.0 + r);
+          }
+          ds = xn * (s * s * s * s);
+          if (s < 0.0) {
+            ds /= (1.0 + s);
+          }
+          dt = xk * (t * t * t * t);
+          if (t < 0.0) {
+            dt /= (1.0 + t);
+          }
+          de = nm * (e * e * e * e);
+          if (e < 0.0) {
+            de /= (1.0 + e);
+          }
+          if (alv < ub - 0.25 * (dr + ds + dt + de)
+                  + (y + m) * (gl - gu) - deltal) {
+            reject = false;
+          } else {
+            /* * Stirling's formula to machine accuracy
+             */
+            if (alv <= (a - afc(ix) - afc(n1 - ix)
+                    - afc(k - ix) - afc(n2 - k + ix))) {
+              reject = false;
+            } else {
+              reject = true;
+            }
+          }
+        }
+      }
+      if (reject) {
+        L30();
+      }
+    }
+  }
