+package r.base.random;
+
+import r.lang.DoubleVector;
+import r.lang.IntVector;
+
+public class Multinomial {
+
+  public static void rmultinom(int n, double[] prob, int K, int[] rN) /*
`Return' vector  rN[1:K] {K := length(prob)}
+   *  where rN[j] ~ Bin(n, prob[j]) ,  sum_j rN[j] == n,  sum_j prob[j] ==
1,
+   */ {
+    int k;
+    double pp;
+    double p_tot = 0.; /* LDOUBLE */
+    /* This calculation is sensitive to exact values, so we try to
+    ensure that the calculations are as accurate as possible
+    so different platforms are more likely to give the same
+    result. */
+
+
+    if (K < 1) {
+      //ML_ERROR(ME_DOMAIN, "rmultinom");
+      return;
+    }
+    if (n < 0) {
+      return;
+    }
+
+    if (K == IntVector.NA || K < 1) {
+      //ML_ERROR(ME_DOMAIN, "rmultinom");
+      return;
+    }
+
+    if (n == IntVector.NA || n < 0) {
+      return;
+    }
+
+
+    /* Note: prob[K] is only used here for checking  sum_k prob[k] = 1 ;
+     *       Could make loop one shorter and drop that check !
+     */
+    for (k = 0; k < K; k++) {
+      pp = prob[k];
+      if (!DoubleVector.isFinite(pp) || pp < 0. || pp > 1.) {
+        //ML_ERR_ret_NAN(k);
+        return;
+      }
+      p_tot += pp;
+      rN[k] = 0;
+    }
+
+    if (Math.abs(p_tot - 1.) > 1e-7) //MATHLIB_ERROR(_("rbinom:
probability sum should be 1, but is %g"), (double) p_tot);
+    {
+      if (n == 0) {
+        return;
+      }
+    }
+
+    if (K == 1 && p_tot == 0.) {
+      return; /* trivial border case: do as rbinom */
+    }
+
+    /* Generate the first K-1 obs. via binomials */
+
+    for (k = 0; k < K - 1; k++) { /* (p_tot, n) are for "remaining
binomial" */
+      if (prob[k] != 0.0) {
+        pp = prob[k] / p_tot;
+        /* printf("[%d] %.17f\n", k+1, pp); */
+        rN[k] = ((pp < 1.) ? (int) Binom.rbinom((double) n, pp)
+                : /*>= 1; > 1 happens because of rounding */ n);
+        n -= rN[k];
+      } else {
+        rN[k] = 0;
+      }
+      if (n <= 0) /* we have all*/ {
+        return;
+      }
+      p_tot -= prob[k]; /* i.e. = sum(prob[(k+1):K]) */
+    }
+    rN[K - 1] = n;
+    return;
+  }
+}
